// AFTER the host recording stops, click real Reset and prove the original
// nine IDs are restored. This sends no skill confirmation to the server.
public static async UniTask RestoreAsync(SkillEditLayer layer, Plan plan, Report report = null)
{
    new Sequence(layer, null, null).Click(layer.nineSlot.ResetButton, "native-unsaved-reset");
    await UniTask.DelayFrame(15);
    Require(SlotIds(layer).SequenceEqual(plan.originalSlotInstances), "Native Reset did not restore all original equipped instances.");
    string[] ranges = { "closeCheckBox", "nearCheckBox", "farCheckBox" };
    for (int i = 0; i < ranges.Length; i++) Field<Toggle>(layer.stonesBox, ranges[i]).SetIsOnWithoutNotify(plan.originalRanges[i]);
    layer.stonesBox.PressTab(plan.originalTab);
    layer.stonesBox.ScrollRect.verticalNormalizedPosition = plan.originalScroll;
    if (report != null) report.resetVerified = true;
}

    var plan = await PocketStrikerStoreSkillSequenceDraft.PrepareAsync(layer);
    StoreVideoNoteAction("prewarmed-three-real-owned-vfx-skills");
    PocketStrikerStoreSkillSequenceDraft.Report evidence = null;
    var recording = StoreVideoRecordClip("skill-editor", 15.5, false).Preserve();
    try
    {
        evidence = await PocketStrikerStoreSkillSequenceDraft.RunAsync(layer, plan, noteAction: StoreVideoNoteAction);
        await recording;
    }
    finally
    {
        StopStoreVideoRecorder();
        if (layer != null) await PocketStrikerStoreSkillSequenceDraft.RestoreAsync(layer, plan, evidence);
        if (evidence != null)
            File.WriteAllText(Path.Combine(StoreOutput, "skill-sequence-report.json"), JsonUtility.ToJson(evidence, true));
    }
    Require(evidence != null && evidence.passed && evidence.resetVerified,
        "Dynamic skill recording or native unsaved reset failed: " + (evidence == null ? "no report" : string.Join("; ", evidence.errors)));
    current.note = "Three actual owned magic VFX previews, two unsaved native inventory equips and one occupied nine-slot swap; all nine original equipment instances restored by native Reset after recording. No skill confirmation or cloud equipment mutation.";
}

static void StoreRestoreState()
{
    if (!SessionState.GetBool(StoreKey + ".Saved", false)) return;
    foreach (var key in StoreIntKeys.Concat(new[] { PlayFabSetting._arenaPointCode }).Where(x => !string.IsNullOrEmpty(x)).Distinct())
    {
        if (SessionState.GetBool(StoreKey + ".Int." + key + ".Had", false)) PlayerPrefs.SetInt(key, SessionState.GetInt(StoreKey + ".Int." + key + ".Value", 0));
        else PlayerPrefs.DeleteKey(key);
    }
    foreach (var key in StoreStringKeys)
    {
        if (SessionState.GetBool(StoreKey + ".String." + key + ".Had", false)) PlayerPrefs.SetString(key, SessionState.GetString(StoreKey + ".String." + key + ".Value", ""));
        else PlayerPrefs.DeleteKey(key);
    }
    PlayerPrefs.Save();
    string path = SessionState.GetString(StoreKey + ".SettingsPath", "");
    bool settingsRestored;
    if (SessionState.GetBool(StoreKey + ".SettingsHad", false))
    {
        byte[] original = Convert.FromBase64String(SessionState.GetString(StoreKey + ".SettingsBytes", ""));
        File.WriteAllBytes(path, original);
        settingsRestored = File.ReadAllBytes(path).SequenceEqual(original);
    }
    else { if (File.Exists(path)) File.Delete(path); settingsRestored = !File.Exists(path); }
    AppSetting.Value.Language = (SystemLanguage)SessionState.GetInt(StoreKey + ".MemoryLanguage", (int)SystemLanguage.English);
    AppSetting.Value.BgmVolume = SessionState.GetFloat(StoreKey + ".Bgm", 1f);
    AppSetting.Value.EffectsVolume = SessionState.GetFloat(StoreKey + ".Effects", 1f);
    EditorUtility.audioMasterMute = SessionState.GetBool(StoreKey + ".AudioMute", false);
    AudioListener.pause = SessionState.GetBool(StoreKey + ".ListenerPause", false);
    AudioListener.volume = SessionState.GetFloat(StoreKey + ".ListenerVolume", 1f);
    bool prefsRestored = StoreIntKeys.Concat(new[] { PlayFabSetting._arenaPointCode }).Where(x => !string.IsNullOrEmpty(x)).Distinct().All(key =>
        PlayerPrefs.HasKey(key) == SessionState.GetBool(StoreKey + ".Int." + key + ".Had", false) &&
        (!PlayerPrefs.HasKey(key) || PlayerPrefs.GetInt(key) == SessionState.GetInt(StoreKey + ".Int." + key + ".Value", 0))) &&
        StoreStringKeys.All(key => PlayerPrefs.HasKey(key) == SessionState.GetBool(StoreKey + ".String." + key + ".Had", false) &&
        (!PlayerPrefs.HasKey(key) || PlayerPrefs.GetString(key) == SessionState.GetString(StoreKey + ".String." + key + ".Value", "")));
    if (storeManifest != null) { storeManifest.preferencesRestored = prefsRestored; storeManifest.appSettingsFileRestored = settingsRestored; }
    SessionState.SetBool(StoreKey + ".Restored", prefsRestored && settingsRestored);
    SessionState.SetBool(StoreKey + ".Saved", false);
    SessionState.EraseString(StoreKey + ".SettingsBytes");
    StoreSaveManifest();

